def run(input):
    import json, re, subprocess
    try:
        body = open(input['body_file'], encoding='utf-8').read()
    except Exception:
        body = ''
    nums = []
    for m in re.finditer(r'#(\d+)', body):
        n = int(m.group(1))
        if n != input['issue_number'] and n not in nums:
            nums.append(n)
    deps = []
    for n in nums[:8]:
        d = {'number': n}
        try:
            r = subprocess.run(['gh', 'issue', 'view', str(n), '-R', input['repo_full'], '--json', 'state,title'], capture_output=True, text=True, timeout=30)
            if r.returncode == 0:
                j = json.loads(r.stdout)
                d.update(kind='issue', state=j.get('state'), title=(j.get('title') or '')[:80])
            else:
                r2 = subprocess.run(['gh', 'pr', 'view', str(n), '-R', input['repo_full'], '--json', 'state,title'], capture_output=True, text=True, timeout=30)
                if r2.returncode == 0:
                    j = json.loads(r2.stdout)
                    d.update(kind='pr', state=j.get('state'), merged=(j.get('state') == 'MERGED'), title=(j.get('title') or '')[:80])
        except Exception:
            pass
        if 'kind' in d:
            deps.append(d)
    return {'deps_json': json.dumps(deps, ensure_ascii=False)}

def run(input):
    import json
    raw = (input.get('text') or '').strip()
    s = raw[raw.find('{'):raw.rfind('}')+1]
    try:
        d = json.loads(s)
        if d.get('verdict') not in ('actionable', 'blocked', 'invalid'):
            d = {'verdict': 'blocked', 'blockers': '分诊输出非法，需人工复核', 'risk': 'low', 'kind': 'unknown', 'acceptance': [], 'commit_message': '', 'notes': 'triage verdict 非法'}
    except Exception:
        d = {'verdict': 'blocked', 'blockers': '分诊输出解析失败，需人工复核原始输出', 'risk': 'low', 'kind': 'unknown', 'acceptance': [], 'commit_message': '', 'notes': 'triage 解析失败'}
    d['acceptance_str'] = '; '.join(d.get('acceptance') or [])
    return d

