def run(input):
    import json
    raw = (input.get('text') or '').strip()

    def _ok(v):
        return isinstance(v, dict) and v.get('verdict') in ('approve', 'fix', 'abort')

    # 提示词要求「输出一行严格 JSON」：先逐行从后往前找；再退化到「最后一个 {
    # 到最后一个 }」的切片。不能用第一个 '{' —— 正文里可能带花括号（#43 实证：
    # 正文含 "type={}, model={}"，旧写法把正文与 JSON 粘成一段，必然解析失败
    # → fail-safe abort，把本该 approve/fix 的 review 误判成叫停）。
    cands = []
    for line in reversed(raw.splitlines()):
        t = line.strip().strip('`').strip()
        if t.startswith('{') and t.endswith('}'):
            cands.append(t)
    lo, lc = raw.rfind('{'), raw.rfind('}')
    if lo != -1 and lc > lo:
        cands.append(raw[lo:lc + 1])

    parsed_any = False
    for c in cands:
        try:
            v = json.loads(c)
        except Exception:
            continue
        if isinstance(v, dict):
            parsed_any = True
            if _ok(v):
                return v
    if parsed_any:
        return {'verdict': 'abort', 'notes': 'review 输出非法 verdict，fail-safe 叫停'}
    return {'verdict': 'abort', 'notes': 'review 输出无法解析，fail-safe 叫停: ' + raw[:150]}

