def run(input):
    import subprocess
    r = subprocess.run(['git', 'diff', '--name-only', 'HEAD'], cwd=input['worktree_dir'], capture_output=True, text=True, timeout=60)
    files = [f for f in r.stdout.splitlines() if f.strip()]
    bad = [f for f in files if f.startswith('.github/') or f.startswith('.worktrees/') or '..' in f or f.startswith('/')]
    n = subprocess.run(['git', 'diff', '--shortstat', 'HEAD'], cwd=input['worktree_dir'], capture_output=True, text=True, timeout=60)
    oversized = False
    if n.stdout and 'insertion' in n.stdout:
        try:
            oversized = int(n.stdout.split('insertion')[0].strip().split()[-1].replace('+','').replace(',','')) > 800
        except Exception:
            oversized = False
    return {'ok': (not bad) and (not oversized), 'violations': bad, 'oversized': oversized}

def run(input):
    import subprocess, re
    wt = input['worktree_dir']
    def sh(args, cwd=None, t=300):
        return subprocess.run(args, cwd=cwd or wt, capture_output=True, text=True, timeout=t)
    lr = sh(['git', 'ls-remote', '--heads', 'origin', input['branch_name']], t=60)
    if lr.stdout.strip():
        return {'pushed': True, 'note': '分支已在远端（续跑/重复投递），跳过重复 push'}
    plan = open(input['artifact_dir'] + '/02-plan.md', encoding='utf-8').read()
    m = re.search(r'^COMMIT_MESSAGE: (.+)$', plan, re.M)
    msg = (m.group(1).strip() if m else ('fix: issue #' + str(input['issue_number'])))
    sh(['git', 'add', '-A'])
    rc = sh(['git', 'commit', '-m', msg])
    rp = sh(['git', 'push', '-u', 'origin', input['branch_name']])
    return {'pushed': rp.returncode == 0, 'note': '' if rp.returncode == 0 else (rp.stderr or '')[-300:]}

def run(input):
    if input.get('push_mode') != 'main':
        return {'merged': None, 'note': 'branch 模式：仅推分支，不合并 main'}
    import subprocess
    mc = input['main_clone']; br = input['branch_name']
    def sh(args, cwd=None):
        return subprocess.run(args, cwd=cwd or mc, capture_output=True, text=True, timeout=300)
    sh(['git', 'fetch', 'origin'])
    r1 = sh(['git', 'merge', '--ff-only', 'origin/' + br])
    if r1.returncode != 0:
        sh(['git', 'merge', '--abort'])
        return {'merged': False, 'note': 'ff 合并失败（main 已前进或分支未推送），分支在远端，请人工合并'}
    r2 = sh(['git', 'push', 'origin', 'HEAD:main'])
    return {'merged': r2.returncode == 0, 'note': '已 ff 合并推送 main' if r2.returncode == 0 else '合并成功但推送失败'}

def run(input):
    import re, subprocess
    t = input.get('text') or ''
    for pat, rep in [(r'/Users/\S+', '[REDACTED-PATH]'), (r'/home/\S+', '[REDACTED-PATH]'), (r'(?i)(api[_-]?key|token|secret|password)\s*[=:]\s*\S+', '[REDACTED-SECRET]')]:
        t = re.sub(pat, rep, t)
    t = t.replace(input.get('artifact_dir') or '', '[ARTIFACT-DIR]')
    # 落地事实由管线追加（模板统一给出，agent 自由文本只讲技术内容）：
    t = t + '\n\n---\n*管线核验：分支 ' + str(input.get('branch_name')) + ' · 推送=' + str(input.get('pushed')) + ' · ' + str(input.get('merged_note')) + '*'
    p = input['artifact_dir'] + '/reply.md'
    open(p, 'w', encoding='utf-8').write(t)
    chk = subprocess.run(['gh', 'issue', 'view', str(input['issue_number']), '-R', input['repo_full'], '--json', 'comments', '--jq', '.comments | map(select(.body | contains("<!-- issue-pipeline -->"))) | length'], capture_output=True, text=True, timeout=60)
    if chk.stdout.strip() not in ('', '0'):
        return {'posted': False, 'note': '已有 pipeline 评论（断点续跑），跳过'}
    r = subprocess.run(['gh', 'issue', 'comment', str(input['issue_number']), '-R', input['repo_full'], '--body-file', p], capture_output=True, text=True, timeout=60)
    return {'posted': r.returncode == 0, 'note': (r.stderr or '')[-200:]}

